#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

K_THREAD_STACK_DEFINE(test_thread_stack, STACK_SIZE);
struct k_thread test_thread_data;

static void test_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);
    /* The thread just needs to exist for the deadline to be set */
    k_thread_suspend(k_current_get()); /* Suspend to prevent it from exiting immediately */
}

/**
 * @brief Test setting a thread deadline
 *
 * This test creates a thread and attempts to set its deadline using
 * k_thread_deadline_set. It verifies that the function call succeeds.
 */
ZTEST(deadline_test_suite, test_deadline_set_api)
{
    k_tid_t tid;
    int ret;

    tid = k_thread_create(&test_thread_data, test_thread_stack, STACK_SIZE,
                          test_thread_entry, NULL, NULL, NULL,
                          K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
    zassert_not_equal(tid, NULL, "Failed to create test thread");

    /*
     * The original error was 'k_thread_dealine_set'.
     * Correcting the typo to 'k_thread_deadline_set'.
     */
    ret = k_thread_deadline_set(tid, 1000); /* Set a deadline of 1000 ticks */
    zassert_equal(ret, 0, "k_thread_deadline_set failed with error: %d", ret);

    k_thread_abort(tid); /* Clean up the created thread */
}

/**
 * @brief Test setting a deadline on the current thread
 */
ZTEST(deadline_test_suite, test_deadline_set_current)
{
    int ret;
    /* Set a deadline for the current thread */
    ret = k_thread_deadline_set(k_current_get(), 500);
    zassert_equal(ret, 0, "k_thread_deadline_set for current thread failed with error: %d", ret);
}

ZTEST_SUITE(deadline_test_suite, NULL, NULL, NULL, NULL, NULL);
